    final String action = record.get(ACTION_TYPE_KEY).toString();
    final String stateTransitionTime = (String) record.get(STATE_TRANSITION_TIME);
    Object actionState = record.get(ACTION_STATE);
    // Very old archived instants don't have the action state set, treat them as completed.
    final HoodieInstant.State state = actionState == null
        ? HoodieInstant.State.COMPLETED : HoodieInstant.State.valueOf(actionState.toString());
    if (loadDetails) {
      getMetadataKey(action, state).map(key -> {
        Object actionData = record.get(key);
        if (actionData != null) {
          // Compaction plans and requested replace-commit metadata are stored as avro records and
          // must be serialized as avro bytes; all the other metadata are stored as their json string form.
          if (action.equals(HoodieTimeline.COMPACTION_ACTION) || action.equals(HoodieTimeline.LOG_COMPACTION_ACTION)
              || (action.equals(HoodieTimeline.REPLACE_COMMIT_ACTION) && state == HoodieInstant.State.REQUESTED)) {
            this.readCommits.put(getInstantDetailsKey(instantTime, state), HoodieAvroUtils.indexedRecordToBytes((IndexedRecord) actionData));
          } else {
            this.readCommits.put(getInstantDetailsKey(instantTime, state), actionData.toString().getBytes(StandardCharsets.UTF_8));
          }
        }
        return null;
      });
    }
    return instantGenerator.createNewInstant(state, action, instantTime, stateTransitionTime);
  }

  /**
   * Returns the archived metadata field that holds the details for the given action and state, or
   * empty when that (action, state) combination does not carry any loadable metadata.
   *
   * <p>CLEAN and ROLLBACK only expose their COMPLETED metadata, and REPLACE_COMMIT does not expose
   * INFLIGHT metadata (its REQUESTED and COMPLETED states are handled separately).
   */
  @Nonnull
  private static Option<String> getMetadataKey(String action, HoodieInstant.State state) {
    switch (action) {
      case HoodieTimeline.CLEAN_ACTION:
        return state == HoodieInstant.State.COMPLETED ? Option.of("hoodieCleanMetadata") : Option.empty();
      case HoodieTimeline.COMMIT_ACTION:
      case HoodieTimeline.DELTA_COMMIT_ACTION:
        return state == HoodieInstant.State.COMPLETED ? Option.of("hoodieCommitMetadata") : Option.empty();
      case HoodieTimeline.ROLLBACK_ACTION:
        return state == HoodieInstant.State.COMPLETED ? Option.of("hoodieRollbackMetadata") : Option.empty();
      case HoodieTimeline.SAVEPOINT_ACTION:
        return state == HoodieInstant.State.COMPLETED ? Option.of("hoodieSavePointMetadata") : Option.empty();
      case HoodieTimeline.COMPACTION_ACTION:
      case HoodieTimeline.LOG_COMPACTION_ACTION:
        // Only the plan (requested/inflight) is archived under the compaction action.
        return state == HoodieInstant.State.COMPLETED ? Option.empty() : Option.of("hoodieCompactionPlan");
      case HoodieTimeline.REPLACE_COMMIT_ACTION:
        if (state == HoodieInstant.State.COMPLETED) {
          return Option.of("hoodieReplaceCommitMetadata");
        } else if (state == HoodieInstant.State.REQUESTED) {
          return Option.of("hoodieRequestedReplaceMetadata");
        } else {
          // Inflight replace-commit metadata is intentionally not loaded.
          return Option.empty();
        }
      case HoodieTimeline.INDEXING_ACTION:
        return state == HoodieInstant.State.COMPLETED ? Option.of("hoodieIndexCommitMetadata") : Option.empty();
      default:
        LOG.error(String.format("Unknown action in metadata (%s)", action));
        return Option.empty();
    }
