88	  private void writeArchivedTimeline(int batchSize, long startTs) throws Exception {
89	    HoodieTestTable testTable = HoodieTestTable.of(this.metaClient);
90	    HoodieWriteConfig writeConfig = HoodieWriteConfig.newBuilder().withPath(this.metaClient.getBasePath())
91	        .withIndexConfig(HoodieIndexConfig.newBuilder().withIndexType(HoodieIndex.IndexType.INMEMORY).build())
92	        .withMarkersType("DIRECT")
93	        .build();
94	    HoodieEngineContext engineContext = new HoodieLocalEngineContext(getDefaultStorageConf());
95	    LSMTimelineWriter writer = LSMTimelineWriter.getInstance(writeConfig, new LocalTaskContextSupplier(), metaClient);
96	    List<ActiveAction> instantBuffer = new ArrayList<>();
97	    for (int i = 1; i <= 50; i++) {
98	      long instantTimeTs = startTs + i;
99	      String instantTime = String.valueOf(instantTimeTs);
100	      String completionTime = String.valueOf(instantTimeTs + 10);
101	      HoodieInstant instant = INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.COMPLETED, "commit", instantTime, completionTime);
102	      HoodieCommitMetadata metadata  = testTable.createCommitMetadata(instantTime, WriteOperationType.INSERT, Arrays.asList("par1", "par2"), 10, false);
103	      byte[] serializedMetadata = TimelineMetadataUtils.serializeCommitMetadata(metaClient.getCommitMetadataSerDe(), metadata).get();
104	      instantBuffer.add(new DummyActiveAction(instant, serializedMetadata));
105	      if (i % batchSize == 0) {
106	        // archive 10 instants each time
107	        writer.write(instantBuffer, org.apache.hudi.common.util.Option.empty(), org.apache.hudi.common.util.Option.empty());
108	        writer.compactAndClean(engineContext);
109	        instantBuffer.clear();
