302	  private HoodieInstant readCommit(String instantTime, GenericRecord record, boolean loadDetails) {
303	    final String action = record.get(ACTION_TYPE_KEY).toString();
304	    final String stateTransitionTime = (String) record.get(STATE_TRANSITION_TIME);
305	    Object actionState = record.get(ACTION_STATE);
306	    // Very old archived instants don't have the action state set, treat them as completed.
307	    final HoodieInstant.State state = actionState == null
308	        ? HoodieInstant.State.COMPLETED : HoodieInstant.State.valueOf(actionState.toString());
309	    if (loadDetails) {
310	      getMetadataKey(action, state).map(key -> {
311	        Object actionData = record.get(key);
312	        if (actionData != null) {
313	          // Compaction plans and requested replace-commit metadata are stored as avro records and
314	          // must be serialized as avro bytes; all the other metadata are stored as their json string form.
315	          if (action.equals(HoodieTimeline.COMPACTION_ACTION) || action.equals(HoodieTimeline.LOG_COMPACTION_ACTION)
316	              || (action.equals(HoodieTimeline.REPLACE_COMMIT_ACTION) && state == HoodieInstant.State.REQUESTED)) {
317	            this.readCommits.put(getInstantDetailsKey(instantTime, state), HoodieAvroUtils.indexedRecordToBytes((IndexedRecord) actionData));
318	          } else {
319	            this.readCommits.put(getInstantDetailsKey(instantTime, state), actionData.toString().getBytes(StandardCharsets.UTF_8));
320	          }
321	        }
322	        return null;
323	      });
324	    }
325	    return instantGenerator.createNewInstant(state, action, instantTime, stateTransitionTime);
326	  }
