328	  /**
329	   * Returns the archived metadata field that holds the details for the given action and state, or
330	   * empty when that (action, state) combination does not carry any loadable metadata.
331	   *
332	   * <p>CLEAN and ROLLBACK only expose their COMPLETED metadata, and REPLACE_COMMIT does not expose
333	   * INFLIGHT metadata (its REQUESTED and COMPLETED states are handled separately).
334	   */
335	  @Nonnull
336	  private static Option<String> getMetadataKey(String action, HoodieInstant.State state) {
337	    switch (action) {
338	      case HoodieTimeline.CLEAN_ACTION:
339	        return state == HoodieInstant.State.COMPLETED ? Option.of("hoodieCleanMetadata") : Option.empty();
340	      case HoodieTimeline.COMMIT_ACTION:
341	      case HoodieTimeline.DELTA_COMMIT_ACTION:
342	        return state == HoodieInstant.State.COMPLETED ? Option.of("hoodieCommitMetadata") : Option.empty();
343	      case HoodieTimeline.ROLLBACK_ACTION:
344	        return state == HoodieInstant.State.COMPLETED ? Option.of("hoodieRollbackMetadata") : Option.empty();
345	      case HoodieTimeline.SAVEPOINT_ACTION:
346	        return state == HoodieInstant.State.COMPLETED ? Option.of("hoodieSavePointMetadata") : Option.empty();
347	      case HoodieTimeline.COMPACTION_ACTION:
348	      case HoodieTimeline.LOG_COMPACTION_ACTION:
349	        // Only the plan (requested/inflight) is archived under the compaction action.
350	        return state == HoodieInstant.State.COMPLETED ? Option.empty() : Option.of("hoodieCompactionPlan");
351	      case HoodieTimeline.REPLACE_COMMIT_ACTION:
352	        if (state == HoodieInstant.State.COMPLETED) {
353	          return Option.of("hoodieReplaceCommitMetadata");
354	        } else if (state == HoodieInstant.State.REQUESTED) {
355	          return Option.of("hoodieRequestedReplaceMetadata");
356	        } else {
357	          // Inflight replace-commit metadata is intentionally not loaded.
358	          return Option.empty();
359	        }
360	      case HoodieTimeline.INDEXING_ACTION:
361	        return state == HoodieInstant.State.COMPLETED ? Option.of("hoodieIndexCommitMetadata") : Option.empty();
362	      default:
363	        LOG.error(String.format("Unknown action in metadata (%s)", action));
364	        return Option.empty();
365	    }
366	  }
